package org.sleepwell.app;
import org.junit.Test;import java.util.concurrent.*;import java.util.concurrent.atomic.*;import static org.junit.Assert.*;
public final class AutoCloudBackupStorageTest {
 @Test public void defaultOffGenericWritesAndFixtureCompletionCannotSchedule()throws Exception{try(AutoCloudBackupFixture f=new AutoCloudBackupFixture()){assertFalse(f.store.owner().enabled);f.queue();assertNull(f.task());assertEquals(0,f.env.schedules);assertEquals(0,f.env.creates);AutoCloudBackups.ended(f.c,f.id,f.start,f.end,false);AutoCloudBackups.drain(5000);assertEquals(0,f.env.schedules);}}
 @Test public void enableRequiresVerifiedSelectedGrantAndDoesNotBackfill()throws Exception{try(AutoCloudBackupFixture f=new AutoCloudBackupFixture()){f.env.grant=false;try{f.enable();fail();}catch(IllegalStateException expected){}assertFalse(f.store.owner().enabled);f.env.grant=true;f.env.failVerify=true;try{f.enable();fail();}catch(java.io.IOException expected){}assertFalse(f.store.owner().enabled);f.env.failVerify=false;f.enable();assertTrue(f.store.owner().enabled);assertEquals(0,f.env.creates);assertEquals(0,f.env.schedules);assertNull(f.task());}}
 @Test public void verifiedVersionIsIdempotentAfterReopenAndRawRecordsStayIdentical()throws Exception{try(AutoCloudBackupFixture f=new AutoCloudBackupFixture()){String before;try(Store s=f.records.open(f.c)){before=BackupFingerprint.read(s);}f.enable();f.queue();assertEquals("PENDING",f.task().state);f.deliver();assertEquals("VERIFIED",f.task().state);assertEquals(1,f.env.creates);assertEquals(1,f.env.documents.size());assertTrue(CloudBackupSettings.history(f.prefs).get(0).verified);try(AutoCloudBackupStore reopened=new AutoCloudBackupStore(f.c,f.journal)){assertEquals(f.task().sha,reopened.task(f.task().identity).sha);assertEquals(64,f.task().sha.length());}f.queue();f.deliver();assertEquals(1,f.env.creates);try(Store s=f.records.open(f.c)){assertEquals(before,BackupFingerprint.read(s));}for(byte[] bytes:f.env.documents.values()){org.json.JSONObject root=new org.json.JSONObject(new String(bytes,java.nio.charset.StandardCharsets.UTF_8));Backup.validate(root);assertFalse(root.has("clips"));assertEquals(1,root.getJSONArray("sessions").length());}}}
 @Test public void precreationPreparationRetriesAreBoundedAndDoNotCreatePartialFiles()throws Exception{try(AutoCloudBackupFixture f=new AutoCloudBackupFixture()){f.enable();f.queue();f.env.failSnapshots=10;for(int n=1;n<=3;n++){f.deliver();assertEquals(n,f.task().attempts);assertEquals(n<3?"PENDING":"FAILED",f.task().state);assertEquals(0,f.env.creates);f.env.now=f.task().due;}f.deliver();assertEquals(3,f.env.snapshots);assertEquals(0,f.env.creates);}}
 @Test public void oversizedMetadataStopsBeforeProviderCreateWithoutPruningOrTransientRetries()throws Exception{try(AutoCloudBackupFixture f=new AutoCloudBackupFixture()){f.enable();f.queue();f.env.oversized=true;f.deliver();assertEquals("FAILED",f.task().state);assertEquals(1,f.task().attempts);assertTrue(f.store.owner().message.contains("8 MiB"));assertEquals(0,f.env.creates);f.deliver();assertEquals(1,f.env.snapshots);try(Store s=f.records.open(f.c)){assertEquals(1,s.rows("SELECT * FROM sessions").size());}}}
 @Test public void createUncertaintyAndHashMismatchNeverBlindlyReplay()throws Exception{try(AutoCloudBackupFixture f=new AutoCloudBackupFixture()){f.enable();f.queue();f.env.createFailure=true;f.deliver();assertEquals("UNCERTAIN",f.task().state);f.deliver();assertEquals(1,f.env.creates);f.env.createFailure=false;f.engine.retry();f.env.corrupt=true;f.deliver();assertEquals("UNCERTAIN",f.task().state);assertFalse(CloudBackupSettings.history(f.prefs).get(0).verified);f.env.corrupt=false;f.engine.retry();f.deliver();assertEquals("VERIFIED",f.task().state);assertEquals(3,f.env.creates);}}
 @Test public void offDestinationAndStaleJobCannotReplayOrSilentlyReenable()throws Exception{try(AutoCloudBackupFixture f=new AutoCloudBackupFixture()){f.enable();f.queue();String old=f.store.owner().token;f.engine.configure(false);assertEquals("CANCELLED",f.task().state);f.engine.run(old,()->true);assertEquals(0,f.env.creates);f.enable();f.queue();assertEquals(0,f.store.count("PENDING"));assertEquals("CANCELLED",f.task().state);CloudBackupSettings.remember(f.prefs,"content://fixture/tree/other","Other folder",0);f.engine.reconcile(false);assertFalse(f.store.owner().enabled);assertTrue(f.store.owner().message.contains("folder changed"));assertEquals(0,f.env.creates);}}
 @Test public void lostGrantCancelsPendingAndChangedOrImportedTriggerIsRejected()throws Exception{try(AutoCloudBackupFixture f=new AutoCloudBackupFixture()){f.enable();f.queue();f.env.grant=false;f.deliver();assertFalse(f.store.owner().enabled);assertEquals("CANCELLED",f.task().state);assertEquals(0,f.env.creates);}try(AutoCloudBackupFixture f=new AutoCloudBackupFixture()){f.enable();f.queue();try(Store s=f.records.open(f.c)){s.getWritableDatabase().execSQL("UPDATE sessions SET origin='imported' WHERE id=?",new Object[]{f.id});}f.deliver();assertEquals("CANCELLED",f.task().state);assertEquals(0,f.env.creates);}}
 @Test public void processRecoveryRetainsUncertainButOnlySafePreparationCanRetry()throws Exception{try(AutoCloudBackupFixture f=new AutoCloudBackupFixture()){f.enable();f.queue();AutoCloudBackupStore.Task task=f.task();f.store.claim(task);f.store.recover();assertEquals("PENDING",f.task().state);f.store.claim(f.task());f.store.stage(f.task(),"CREATING",null);f.store.recover();assertEquals("UNCERTAIN",f.task().state);f.engine.reconcile(true);assertEquals(0,f.env.creates);assertEquals("",f.env.scheduled);}}
 @Test public void lateReturnedDocumentAndVerifiedReceiptRemainAfterDurableOff()throws Exception{try(AutoCloudBackupFixture f=new AutoCloudBackupFixture()){f.enable();f.queue();AutoCloudBackupStore.Task t=f.task();f.store.claim(t);f.store.stage(t,"CREATING",null);f.engine.configure(false);assertEquals("UNCERTAIN",f.task().state);CloudBackupCopy.Document document=new CloudBackupCopy.Document("content://fixture/tree/backups/document/late","late.json");f.store.stage(t,"CREATED",document);assertEquals("UNCERTAIN",f.task().state);assertEquals(document.uri,f.task().uri);f.store.complete(t,new CloudBackupCopy.Receipt(document,42,"a".repeat(64)));assertEquals("VERIFIED",f.task().state);assertFalse(f.store.owner().enabled);assertTrue(f.store.owner().message.startsWith("Off"));f.enable();f.queue();assertEquals("VERIFIED",f.task().state);assertEquals(0,f.store.count("PENDING"));}}
 @Test public void offPersistsWhileProviderIsBlockedAndDoesNotReleaseUploadLease()throws Exception{try(AutoCloudBackupFixture f=new AutoCloudBackupFixture()){Records.Factory oldRecords=Records.factory;AutoCloudBackups.Factory oldFactory=AutoCloudBackups.factory;AutoCloudBackups.Environments oldEnvironment=AutoCloudBackups.environments;AutoCloudBackups.State oldState=AutoCloudBackups.state;CloudBackupSettings.Factory oldSettings=CloudBackupSettings.factory;CountDownLatch done=new CountDownLatch(1);try{AutoCloudBackups.drain(5000);Records.factory=f.records;AutoCloudBackups.factory=c->new AutoCloudBackupStore(c,f.journal);AutoCloudBackups.environments=(c,r)->f.env;CloudBackupSettings.factory=c->f.prefs;f.enable();f.queue();f.env.hold=true;AutoCloudBackups.run(f.c,f.store.owner().token,new AtomicBoolean(),done::countDown);assertTrue(f.env.blocked.await(10,TimeUnit.SECONDS));AutoCloudBackups.configure(f.c,false);long until=android.os.SystemClock.elapsedRealtime()+5000;while(f.store.owner().enabled&&android.os.SystemClock.elapsedRealtime()<until)Thread.sleep(10);assertFalse("Off is durable independently of a blocked provider",f.store.owner().enabled);assertEquals("UNCERTAIN",f.task().state);assertFalse(f.task().uri.isEmpty());Object probe=new Object();assertFalse(CloudBackupLease.acquire(probe));assertEquals(1,f.env.creates);AutoCloudBackups.configure(f.c,true);assertFalse("On cannot race cleanup",f.store.owner().enabled);f.env.release.countDown();assertTrue(done.await(10,TimeUnit.SECONDS));AutoCloudBackups.drain(5000);assertFalse(f.store.owner().enabled);assertFalse(AutoCloudBackups.state.busy);assertEquals("UNCERTAIN",f.task().state);assertFalse(f.task().uri.isEmpty());assertTrue(CloudBackupLease.acquire(probe));CloudBackupLease.release(probe);assertEquals(1,f.env.creates);}finally{f.env.release.countDown();assertTrue(done.await(10,TimeUnit.SECONDS));AutoCloudBackups.drain(5000);Records.factory=oldRecords;AutoCloudBackups.factory=oldFactory;AutoCloudBackups.environments=oldEnvironment;CloudBackupSettings.factory=oldSettings;AutoCloudBackups.state=oldState;}}}
 @Test public void cancellationKeepsProviderLeaseUntilBlockedIoAndCleanupActuallyReturn()throws Exception{try(AutoCloudBackupFixture f=new AutoCloudBackupFixture()){f.enable();f.queue();f.env.hold=true;AtomicBoolean current=new AtomicBoolean(true);AtomicReference<Throwable> failure=new AtomicReference<>();Thread worker=new Thread(()->{try{f.engine.run(f.store.owner().token,current::get);}catch(Throwable e){failure.set(e);}},"fake-provider-held");worker.start();assertTrue(f.env.blocked.await(10,TimeUnit.SECONDS));current.set(false);f.engine.cancelProvider();Object probe=new Object();assertFalse("Cancellation is not a provider cleanup acknowledgement",CloudBackupLease.acquire(probe));assertEquals(1,f.env.providerCancels);f.env.release.countDown();worker.join(10000);assertFalse(worker.isAlive());assertNull(failure.get());assertEquals("UNCERTAIN",f.task().state);assertTrue(CloudBackupLease.acquire(probe));CloudBackupLease.release(probe);assertEquals(1,f.env.creates);}}
}
